164	        const hubs = (LEAF.has(a.type) ? 0 : 1) + (LEAF.has(b.type) ? 0 : 1);
165	        const f = (1600 + hubs * 2600) / d2; const d = Math.sqrt(d2); const fx = dx / d * f, fy = dy / d * f;
