171	      const rest = LEAF.has(a.type) && LEAF.has(b.type) ? 60 : 130; const f = (d - rest) * 0.018;
172	      a.vx += dx / d * f; a.vy += dy / d * f; b.vx -= dx / d * f; b.vy -= dy / d * f;
173	    }
174	    for (const a of nodes) { const g = LEAF.has(a.type) ? 0.0035 : 0.002; a.vx -= a.x * g; a.vy -= a.y * g; a.x += a.vx * alpha * 0.6; a.y += a.vy * alpha * 0.6; a.vx *= 0.5; a.vy *= 0.5; }
175	  }
176	}
