510	const LANE_COLOR = { human: 'var(--human)', s: 'var(--s)', d: 'var(--d)', store: 'var(--store)', gate: 'var(--gate)' };
511	const TYPE_LABEL = { D: 'D', S: 'S', DS: 'D+S', GATE: 'GATE', HUMAN: 'HUMAN', STORE: 'RECORD' };
512	const TYPE_COLOR = { D: 'var(--d)', S: 'var(--s)', DS: 'var(--ink-2)', GATE: 'var(--gate)', HUMAN: 'var(--human)', STORE: 'var(--store)' };
