516	const GUTTER = 150, COLW = 170, NODEW = 134, NODEH = 58, LANEH = 96, TOP = 18;
517	
518	function nodePos(stage) {
519	  const laneIndex = LANES.findIndex(l => l.id === stage.lane);
520	  const x = GUTTER + (stage.col - 1) * COLW;
521	  const y = TOP + laneIndex * LANEH + (LANEH - NODEH) / 2;
522	  return { x, y, cx: x + NODEW / 2, cy: y + NODEH / 2 };
523	}
