525	function wrapTitle(title) {
526	  const words = title.split(' ');
527	  const lines = [];
528	  let line = '';
529	  for (const w of words) {
530	    if ((line + ' ' + w).trim().length > 19 && line) { lines.push(line); line = w; } else line = (line + ' ' + w).trim();
531	  }
532	  if (line) lines.push(line);
533	  return lines.slice(0, 2);
534	}
