536	function renderSvg(wf) {
537	  const cols = Math.max(...wf.stages.map(s => s.col));
538	  const width = GUTTER + cols * COLW + 20;
539	  const height = TOP + LANES.length * LANEH + 12;
540	  let out = `<svg viewBox="0 0 ${width} ${height}" width="${width}" height="${height}" role="img" aria-label="${esc(wf.code)} swimlane diagram">`;
541	  out += `<defs><pattern id="hatch-${wf.id}" width="6" height="6" patternUnits="userSpaceOnUse" patternTransform="rotate(45)"><rect width="6" height="6" fill="var(--surface)"/><line x1="0" y1="0" x2="0" y2="6" stroke="var(--hair)" stroke-width="1.5"/></pattern><marker id="arrow-${wf.id}" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="7" markerHeight="7" orient="auto-start-reverse"><path d="M0,0 L10,5 L0,10 z" fill="context-stroke"/></marker></defs>`;
542	  LANES.forEach((lane, i) => {
543	    const y = TOP + i * LANEH;
544	    out += `<rect x="0" y="${y}" width="${width}" height="${LANEH}" fill="${i % 2 ? 'var(--band-b)' : 'var(--band-a)'}"/>`;
545	    out += `<rect x="0" y="${y}" width="4" height="${LANEH}" fill="${LANE_COLOR[lane.id]}"/>`;
546	    out += `<text class="lane-label" x="14" y="${y + 18}">${esc(lane.label)}</text>`;
547	  });
548	  const byN = Object.fromEntries(wf.stages.map(s => [s.n, s]));
549	  // edges first
550	  wf.edges.forEach((e, idx) => {
551	    const [a, b, schema, kind] = e;
552	    const A = nodePos(byN[a]), B = nodePos(byN[b]);
553	    const forward = B.x > A.x;
554	    const kindClass = kind || 'flow';
555	    let d, lx, ly;
556	    if (forward) {
557	      const x1 = A.x + NODEW, y1 = A.cy, x2 = B.x, y2 = B.cy;
558	      const dx = Math.max(30, (x2 - x1) / 2);
559	      d = `M${x1},${y1} C${x1 + dx},${y1} ${x2 - dx},${y2} ${x2},${y2}`;
560	      lx = (x1 + x2) / 2;
561	      // A hand-off inside one lane has no room between the boxes: write it in the band above them.
562	      ly = Math.abs(y1 - y2) < 6 ? A.y - 9 : (y1 + y2) / 2 - 8;
563	    } else {
564	      const x1 = A.cx, y1 = A.y + NODEH, x2 = B.cx, y2 = B.y + NODEH;
565	      const drop = TOP + LANES.length * LANEH - 4;
566	      d = `M${x1},${y1} C${x1},${drop} ${x2},${drop} ${x2},${y2}`;
567	      lx = (x1 + x2) / 2; ly = drop - 12;
568	    }
569	    const label = schema;
570	    const lw = label.length * 6.4 + 12;
571	    out += `<g class="edge ${kindClass}" data-edge="${idx}" data-from="${a}" data-to="${b}" data-schema="${esc(schema)}" tabindex="0" role="button" aria-label="Hand-off ${esc(schema)} from stage ${a} to stage ${b}">`;
572	    out += `<path d="${d}" marker-end="url(#arrow-${wf.id})"/>`;
573	    out += `<rect x="${lx - lw / 2}" y="${ly - 9}" width="${lw}" height="15" rx="3"/>`;
574	    out += `<text x="${lx}" y="${ly + 2.5}" text-anchor="middle">${esc(label)}</text></g>`;
575	  });
576	  wf.stages.forEach(s => {
577	    const p = nodePos(s);
578	    const lines = wrapTitle(s.title);
579	    out += `<g class="node svg-node t-${s.type} st-${s.status || 'implemented'}${s.outsideLog ? ' outside' : ''}${s.revised ? ' revised' : ''}" data-stage="${s.n}" data-col="${s.col}" tabindex="0" role="button" aria-label="Stage ${s.n}: ${esc(s.title)}">`;
580	    out += `<rect class="box" x="${p.x}" y="${p.y}" width="${NODEW}" height="${NODEH}" rx="7"${s.outsideLog ? ` fill="url(#hatch-${wf.id})"` : ''}/>`;
581	    out += `<rect x="${p.x}" y="${p.y}" width="5" height="${NODEH}" rx="2" fill="${TYPE_COLOR[s.type]}"/>`;
582	    if (s.type === 'DS') out += `<rect x="${p.x}" y="${p.y}" width="5" height="${NODEH / 2}" rx="2" fill="var(--d)"/><rect x="${p.x}" y="${p.y + NODEH / 2}" width="5" height="${NODEH / 2}" rx="2" fill="var(--s)"/>`;
583	    out += `<text class="num" x="${p.x + 12}" y="${p.y + 13}">${s.n}</text>`;
584	    if (s.revised) out += `<circle class="rev-dot" cx="${p.x + NODEW - 8}" cy="${p.y + NODEH - 8}" r="3.5"><title>Revised after the council (${esc(s.revised)})</title></circle>`;
585	    out += `<text class="tag" x="${p.x + NODEW - 8}" y="${p.y + 13}" text-anchor="end" fill="${TYPE_COLOR[s.type]}">${TYPE_LABEL[s.type]}</text>`;
586	    lines.forEach((ln, i) => { out += `<text class="title" x="${p.x + 12}" y="${p.y + 29 + i * 13}">${esc(ln)}</text>`; });
587	    out += `<text class="actor" x="${p.x + 12}" y="${p.y + NODEH - 8}">${esc(s.actor.length > 22 ? s.actor.slice(0, 21) + '…' : s.actor)}</text>`;
588	    out += `</g>`;
589	  });
590	  out += `</svg>`;
591	  return out;
592	}
